-- Minimal faithful fixture of the legacy atina-ranking objects used by the v2 upgrade.
-- Synthetic data only. Never run against a hosted Supabase project.
create schema if not exists private;

create table private.atina_challenges (
  challenge_id integer primary key,
  category text not null,
  emoji text not null,
  clues jsonb not null,
  answer text not null,
  accepted_answers jsonb not null,
  image_url text,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  difficulty text check (difficulty in ('easy','medium','hard'))
);
alter table private.atina_challenges enable row level security;
revoke all on private.atina_challenges from public, anon, authenticated;
insert into private.atina_challenges
(challenge_id,category,emoji,clues,answer,accepted_answers,difficulty)
values (1,'fixture','🧪','["a","b","c","d","e"]','teste','["teste"]','easy');

create table public.atina_rooms (
  id uuid primary key,
  code text not null unique check (code ~ '^[A-Z0-9]{6}$'),
  host_player_id uuid not null,
  max_players integer not null default 12 check (max_players between 1 and 12),
  status text not null default 'waiting' check (status in ('waiting','playing','finished')),
  created_at timestamptz not null default now(),
  game_state jsonb not null default '{}'::jsonb,
  state_version bigint not null default 0
);
create table public.atina_room_players (
  id uuid primary key,
  room_id uuid not null references public.atina_rooms(id),
  nickname text not null check (char_length(nickname) between 1 and 20),
  token_hash text not null,
  is_host boolean not null default false,
  joined_at timestamptz not null default now(),
  last_seen_at timestamptz not null default now(),
  team_label text,
  is_ready boolean not null default false,
  score integer not null default 0
);

create table public.atina_room_answers (
  id bigint generated always as identity primary key,
  room_id uuid not null references public.atina_rooms(id),
  player_id uuid not null references public.atina_room_players(id),
  challenge_index integer not null,
  is_correct boolean not null,
  points integer not null,
  created_at timestamptz not null default now()
);
create table public.atina_team_proposals (
  id uuid primary key default gen_random_uuid(),
  room_id uuid not null references public.atina_rooms(id),
  challenge_index integer not null,
  team_label text not null,
  proposer_id uuid not null references public.atina_room_players(id),
  answer_text text not null,
  is_correct boolean not null,
  points integer not null default 0,
  status text not null default 'pending',
  created_at timestamptz not null default now()
);
create table public.atina_team_votes (
  proposal_id uuid not null references public.atina_team_proposals(id),
  player_id uuid not null references public.atina_room_players(id),
  agrees boolean not null,
  created_at timestamptz not null default now(),
  primary key (proposal_id,player_id)
);
create table public.atina_multiplayer_ranking (
  id bigint generated always as identity primary key,
  room_id uuid not null references public.atina_rooms(id),
  player_id uuid not null references public.atina_room_players(id),
  nickname text not null,
  team_label text,
  score integer not null default 0,
  created_at timestamptz not null default now()
);
create table public.atina_room_results (
  id bigint generated always as identity primary key,
  room_id uuid not null references public.atina_rooms(id),
  player_id uuid not null references public.atina_room_players(id),
  nickname text not null,
  team_label text,
  score integer not null default 0,
  completed_at timestamptz not null default now()
);
create table public.atina_room_timeout_budgets (
  room_id uuid not null references public.atina_rooms(id),
  scope text not null,
  scope_key text not null,
  used_seconds integer not null default 0,
  updated_at timestamptz not null default now(),
  primary key (room_id,scope,scope_key)
);

create table private.atina_mime_cards (
  id bigint generated by default as identity primary key,
  word text not null,
  category text not null,
  clues jsonb not null check (jsonb_typeof(clues)='array' and jsonb_array_length(clues)=5)
);
alter table private.atina_mime_cards enable row level security;
revoke all on private.atina_mime_cards from public, anon, authenticated;
insert into private.atina_mime_cards(word,category,clues)
select 'carta-'||n,'fixture',jsonb_build_array('pista 1','pista 2','pista 3','pista 4','pista 5')
from generate_series(1,48) n;

create table private.atina_mime_secrets (
  room_id uuid not null references public.atina_rooms(id),
  round_number integer not null,
  card_id bigint not null references private.atina_mime_cards(id),
  representative_id uuid not null references public.atina_room_players(id),
  word text not null,
  created_at timestamptz not null default now(),
  primary key(room_id,round_number)
);
alter table private.atina_mime_secrets enable row level security;
revoke all on private.atina_mime_secrets from public, anon, authenticated;

insert into public.atina_rooms(id,code,host_player_id)
select ('10000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,
       'OLD'||lpad(n::text,3,'0'),
       ('20000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid
from generate_series(1,4) n;
insert into public.atina_room_players(id,room_id,nickname,token_hash,is_host,is_ready)
select ('20000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,
       ('10000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,
       'Jogador '||n,repeat(n::text,64),true,true
from generate_series(1,4) n;

-- Stable legacy RPC sentinels: the v2 upgrade must not replace these names/contracts.
create or replace function public.atina_room_state(p_room_id uuid,p_token text)
returns jsonb language sql security definer set search_path=''
as $$ select jsonb_build_object('legacy_contract',true); $$;
create or replace function public.atina_create_room(p_nickname text,p_max_players integer)
returns jsonb language sql security definer set search_path=''
as $$ select jsonb_build_object('legacy_contract',true); $$;
